module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
localparam TxIdle = 2'b00;
	localparam Sending = 2'b01;
	localparam TxDone = 2'b10;
	localparam RxIdle = 2'b00;
	localparam Receiving = 2'b01;
	localparam RxDone = 2'b10;
	reg [1:0] TxState;
	reg [1:0] RxState;
	reg [7:0] RxData;
	reg [7:0] TxData;
	reg [7:0] TxBdCount;
	reg [7:0] RxBdCount;
	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			TxState <= TxIdle;
			RxState <= RxIdle;
			opTxBusy <= 1'b0;
			opTx <= 1'b0;
			opRxValid <= 1'b0;
			opRxData <= 8'b0;
			TxBdCount <= 8'b0;
			RxBdCount <= 8'b0;
		end
		else begin
			case (TxState)
				TxIdle: begin
					if (ipTxSend) begin
						TxState <= Sending;
						opTxBusy <= 1'b1;
						TxBdCount <= 8'b0;
						TxData <= {1'b0,ipTxData,1'b1};
					end
					else begin
						opTxBusy <= 1'b0;
					end
				end
				Sending: begin
					if (TxBdCount == 8) begin
						TxState <= TxDone;
					end
					else begin
						opTx <= TxData[TxBdCount];
						TxBdCount <= TxBdCount + 1;
					end
				end
				TxDone: begin
					TxState <= TxIdle;
					opTxBusy <= 1'b0;
				end
			endcase
			case (RxState)
				RxIdle: begin
					if (ipRx == 1'b0) begin
						RxState <= Receiving;
						RxBdCount <= 8'b0;
						RxData <= 8'b0;
					end
					else begin
						opRxValid <= 1'b0;
					end
				end
				Receiving: begin
					if (RxBdCount == 8) begin
						RxState <= RxDone;
					end
					else begin
						RxData[RxBdCount] <= ipRx;
						RxBdCount <= RxBdCount + 1;
					end
				end
				RxDone: begin
					RxState <= RxIdle;
					opRxValid <= 1'b1;
					opRxData <= RxData;
				end
			endcase
		end
	end
endmodule

