        hsync_reg <= 1;
    end
    else begin
        hsync_reg <= 0;
    end
    if(v_counter < V_SYNC) begin
        vsync_reg <= 1;
    end
    else if(v_counter < V_SYNC + V_BACK) begin
        vsync_reg <= 0;
    end
    else if(v_counter < V_TOTAL - V_FRONT) begin
        vsync_reg <= 1;
    end
    else begin
        vsync_reg <= 0;
    end
    if(h_counter < H_TOTAL - 1) begin
        visible_region_reg <= 1;
    end
    else begin
        visible_region_reg <= 0;
    end
end
assign hsync = hsync_reg;
assign vsync = vsync_reg;
assign pixel_x = h_counter;
assign pixel_y = v_counter;
assign visible_region = visible_region_reg;
endmodule

