module comparator (output reg [2:0] result, input [15:0] X, Y, input clk);
always @(posedge clk) begin
    if (X[15] != Y[15]) begin
        if (X[15]) begin
            result <= 3'b100;
        end else begin
            result <= 3'b010;
        end
    end else if (X[14:10] != Y[14:10]) begin
        if (X[14:10] > Y[14:10]) begin
            result <= 3'b100;
        end else begin
            result <= 3'b010;
        end
    end else if (X[9:0] != Y[9:0]) begin
        if (X[9:0] > Y[9:0]) begin
            result <= 3'b100;
        end else begin
            result <= 3'b010;
        end
    end else begin
        result <= 3'b001;
    end
end
endmodule

