module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [1:0]
  S_0 = 0,
  S_ED_T4 = 1,
  S_4D_T4 = 2,
  S_CB_T4 = 3;
reg [1:0] state;
reg [1:0] next_state;
reg ifetch;
reg ifetch_cancel;
reg [7:0] cpu_opcode;
  always @(posedge i_CLK_CPU, posedge i_reset) begin
    if((i_reset == 1'b1)) begin
      state <= S_0;
    end else begin
      state <= next_state;
    end
  end
  always @(state, ifetch, ifetch_cancel, cpu_opcode) begin
    next_state = state;
    ifetch = 1'b0;
    ifetch_cancel = 1'b0;
    case(state)
    S_0 : begin
      if((ifetch_cancel == 1'b0)) begin
        if((i_mreq_n == 1'b0)) begin
          ifetch = 1'b1;
        end
      end
      if((ifetch == 1'b1)) begin
        if((i_mreq_n == 1'b1)) begin
          ifetch_cancel = 1'b1;
        end
      end
      if((ifetch_cancel == 1'b0)) begin
        if((i_mreq_n == 1'b0)) begin
          cpu_opcode <= i_cpu_d;
        end
      end
      if((cpu_opcode == 8'hED)) begin
        next_state = S_ED_T4;
      end
      if((cpu_opcode == 8'h4D)) begin
        next_state = S_4D_T4;
      end
      if((cpu_opcode == 8'hCB)) begin
        next_state = S_CB_T4;
      end
    end
    S_ED_T4 : begin
      next_state = S_0;
    end
    S_4D_T4 : begin
      next_state = S_0;
    end
    S_CB_T4 : begin
      next_state = S_0;
    end
    default : begin
    end
    endcase
  end
  assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : 1'b0;
  assign o_reti_seen = (state == S_ED_T4) ? 1'b1 : 1'b0;
endmodule

