module CAS(
	input [3:0] IN,
	output [3:0] OUT
	);
assign OUT[0] = IN[0] & IN[1] | IN[2] & IN[3] | IN[0] & IN[2] | IN[1] & IN[3];
	assign OUT[1] = IN[0] ^ IN[1] ^ IN[2] ^ IN[3];
	assign OUT[2] = IN[1];
	assign OUT[3] = IN[0];
endmodule

module FIFO_toe_rtTimer2stateTable_releaseStat_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output [DATA_WIDTH-1:0] q;
parameter DATA_WIDTH = 32'd16;
parameter ADDR_WIDTH = 32'd2;
parameter DEPTH = 32'd3;

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
    begin
        if (ce)
        begin
            for (i=0;i<DEPTH-1;i=i+1)
                SRL_SIG[i+1] <= SRL_SIG[i];
            SRL_SIG[0] <= data;
        end
    end

assign q = SRL_SIG[a];

endmodule

module mode0(
input wire clk_i,
input wire [9:0] pix_x_i,
input wire [9:0] pix_y_i,
output reg [16:0] vram_addr_o,
input wire [7:0] vram_rd_data_i,
output reg [7:0] pal_addr_o,
input wire [11:0] pal_rd_data_i,
input wire [16:0] mapbase_i,
input wire [16:0] tilebase_i,
output reg [11:0] col_o,
output reg [9:0] delay_o
); 

reg [9:0] pix_x_0r;
reg [9:0] pix_x_1r;
reg [9:0] pix_x_2r;
reg [9:0] pix_x_3r;
reg [9:0] pix_x_4r;
reg [9:0] pix_y_0r;
reg [9:0] pix_y_1r;
reg [9:0] pix_y_2r;
reg [9:0] pix_y_3r;
reg [9:0] pix_y_4r;
  always @(posedge clk_i) begin
    pix_x_0r <= pix_x_i;
    pix_x_1r <= pix_x_0r;
    pix_x_2r <= pix_x_1r;
    pix_x_3r <= pix_x_2r;
    pix_x_4r <= pix_x_3r;
    pix_y_0r <= pix_y_i;
    pix_y_1r <= pix_y_0r;
    pix_y_2r <= pix_y_1r;
    pix_y_3r <= pix_y_2r;
    pix_y_4r <= pix_y_3r;
  end
  always @(posedge clk_i) begin
    case(pix_x_4r[2:0])
    3'b000 : begin
      vram_addr_o <= {1'b0,mapbase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b001 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b010 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b011 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b100 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b101 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b110 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    3'b111 : begin
      vram_addr_o <= {1'b0,tilebase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    default : begin
      vram_addr_o <= {1'b0,mapbase_i[11:0],pix_y_4r[9:0],pix_x_4r[9:0]};
    end
    endcase
  end
  always @(posedge clk_i) begin
    pal_addr_o <= pal_rd_data_i[11:0];
  end
  always @(posedge clk_i) begin
    col_o <= pal_rd_data_i[7:0];
  end
  always @(posedge clk_i) begin
    delay_o <= pix_x_i[9:0];
  end
endmodule

