  generate
    genvar i;
    for (i = 0; i < DP; i = i + 1) begin
      if (i == 0) begin
        rom_data[i] = 32'h00000000;
      end
      else if (i == 1) begin
        rom_data[i] = 32'h00000000;
      end
      else begin
        rom_data[i] = 32'h00000000;
      end
    end
  endgenerate

  assign rom_dout = rom_data[rom_addr[AW-1:2]];

endmodule

