module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          state_p1;
reg          state_p2;
reg          s_ready_reg;
reg          m_valid_reg;

assign s_ready = s_ready_reg;
assign m_data  = data_p2;
assign m_valid = m_valid_reg;

always @(posedge clk) begin
    case (state_p1)
        ZERO: begin
            if (s_valid) begin
                data_p1 <= s_data;
                state_p1 <= ONE;
            end
        end
        ONE: begin
            if (s_ready) begin
                data_p1 <= s_data;
                state_p1 <= TWO;
            end
        end
        TWO: begin
            if (m_ready) begin
                data_p1 <= data_p2;
                state_p1 <= ONE;
            end
        end
        default: state_p1 <= ZERO;
    endcase
end

always @(posedge clk) begin
    case (state_p2)
        ZERO: begin
            if (s_valid) begin
                data_p2 <= s_data;
                state_p2 <= ONE;
            end
        end
        ONE: begin
            if (s_ready) begin
                data_p2 <= s_data;
                state_p2 <= TWO;
            end
        end
        TWO: begin
            if (m_ready) begin
                state_p2 <= ONE;
            end
        end
        default: state_p2 <= ZERO;
    endcase
end

always @(posedge clk) begin
    if (reset) begin
        s_ready_reg <= 1'b0;
    end else begin
        case (state_p1)
            ZERO: begin
                s_ready_reg <= 1'b0;
            end
            ONE: begin
                s_ready_reg <= 1'b1;
            end
            TWO: begin
                s_ready_reg <= 1'b1;
            end
            default: s_ready_reg <= 1'b0;
        endcase
