module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state;
   reg [35:0] data0_o, data1_o;
   reg src0_rdy_o, src1_rdy_o;
   reg eof;
   always @(posedge clk or posedge reset or posedge clear)
     if (reset || clear)
       state <= IDLE;
     else
       case (state)
	 IDLE: if (src_rdy_i)
		  if (match_data == data_i && match_mask == data_i[35:16])
		    state <= DATA0;
		  else
		    state <= DATA1;
	 DATA0: if (dst0_rdy_i)
		  state <= IDLE;
	 DATA1: if (dst1_rdy_i)
		  state <= IDLE;
       endcase
   always @(state, data_i)
     case (state)
       IDLE: begin
		data0_o <= 0;
		data1_o <= 0;
		src0_rdy_o <= 0;
		src1_rdy_o <= 0;
		eof <= 0;
       end
       DATA0: begin
		data0_o <= data_i;
		data1_o <= 0;
		src0_rdy_o <= 1;
		src1_rdy_o <= 0;
		eof <= data_i[35];
       end
       DATA1: begin
		data0_o <= 0;
		data1_o <= data_i;
		src0_rdy_o <= 0;
		src1_rdy_o <= 1;
		eof <= data_i[35];
       end
     endcase
   assign dst_rdy_o = state == IDLE;
endmodule

