module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [AW-1:0] subaddr;
    reg good;
    always @(*) begin
        if (DW == 8) begin
            addr_req = {addr[AW-1:0], 8'h00};
        end
        else if (DW == 16) begin
            addr_req = {addr[AW-1:0], 16'h0000};
        end
        else if (DW == 32) begin
            addr_req = {addr[AW-1:0], 32'h00000000};
        end
    end
    always @(*) begin
        if (addr_req == cached_addr0) begin
            hit0 = 1;
        end
        else begin
            hit0 = 0;
        end
        if (addr_req == cached_addr1) begin
            hit1 = 1;
        end
        else begin
            hit1 = 0;
        end
    end
    always @(*) begin
        if (addr_req[AW-1:0] == 0) begin
            subaddr = 0;
        end
        else begin
            subaddr = addr_req[AW-1:0] - 1;
        end
    end
    always @(*) begin
        if (addr_ok && we) begin
            if (DW == 8) begin
                cached_data0 = din[7:0];
                cached_data1 = din[15:8];
            end
            else if (DW == 16) begin
                cached_data0 = din[15:0];
                cached_data1 = din[31:16];
            end
            else if (DW == 32) begin
                cached_data0 = din[31:0];
                cached_data1 = din[63:32];
            end
            cached_addr0 = addr_req;
            cached_addr1 = addr_req + 1;
            good = 1;
        end
        else begin
            good = 0;
        end
    end
    always @(*) begin
        if (addr_ok) begin
            if (hit0) begin
                data_ok = 1;
            end
            else if (hit1) begin
                data_ok = 1;
            end
            else begin
                data_ok = 0;
            end
        end
        else begin
            data_ok = 0;
        end
    end
    always @(*) begin
        if (addr_ok) begin
            if (hit0) begin
                dout = cached_data0;
            end
            else if (hit1) begin
                dout = cached_data1;
            end
            else begin
                dout = din;
            end
        end
        else begin
            dout = 0;
        end
    end
    always @(*) begin
        if (addr_ok) begin
            if (subaddr == 0) begin
                sdram_addr = addr_req + offset;
            end
            else begin
                sdram_addr = addr_req + offset + 1;
            end
        end
        else begin
            sdram_addr = 0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            req <= 0;
        end
        else begin
            if (addr_ok && we) begin
                req <= 1;
            end
            else if (addr_ok && !we) begin
                req <= 0;
            end
            else begin
                req <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            good <= 0;
        end
        else begin
            if (addr_ok && we) begin
                good <= 1;
            end
            else begin
                good <= 0;
            end
        end
    end
endmodule

