module Data_Memory(
	input reset,
	input [31:0] address,
	input [31:0] write_data,
	input memRead,
	input memWrite,
	input [2:0] func3,
	output reg [31:0] read_data
    );
reg [7:0] mem [0:2**20-1];
initial begin
	$readmemb("data_memory.txt", mem);
end
always @(reset, address, write_data, memRead, memWrite, func3) begin
	if (reset) begin
		read_data <= 0;
	end else begin
		if (memRead) begin
			if (func3 == 3'b000) begin
				read_data <= mem[address];
			end else if (func3 == 3'b001) begin
				read_data <= {mem[address+1], mem[address]};
			end else if (func3 == 3'b010) begin
				read_data <= {mem[address+2], mem[address+1], mem[address]};
			end else if (func3 == 3'b011) begin
				read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
			end else if (func3 == 3'b100) begin
				read_data <= {mem[address+1], mem[address]};
			end else if (func3 == 3'b101) begin
				read_data <= {mem[address+2], mem[address+1], mem[address]};
			end else if (func3 == 3'b110) begin
				read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
			end else if (func3 == 3'b111) begin
				read_data <= {mem[address+1], mem[address]};
			end else begin
				read_data <= {mem[address+2], mem[address+1], mem[address]};
			end
		end else if (memWrite) begin
			if (func3 == 3'b000) begin
				mem[address] <= write_data[7:0];
			end else if (func3 == 3'b001) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
			end else if (func3 == 3'b010) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
			end else if (func3 == 3'b011) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
				mem[address+3] <= write_data[31:24];
			end else if (func3 == 3'b100) begin
				mem[address] <= write_data[7:0];
			end else if (func3 == 3'b101) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
			end else if (func3 == 3'b110) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
			end else if (func3 == 3'b111) begin
				mem[address] <= write_data[7:0];
			end else begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
			end
		end else begin
			read_data <= 0;
		end
	end
end
endmodule

module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  reg       ready;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state <= 4'h0;
      data  <= 8'h0;
      ready <= 1'b0;
    end else begin
      case (state)
        4'h0: begin
          if (io_valid) begin
            state <= 4'h1;
            data  <= io_bits;
          end
        end
        4'h1: begin
          if (tick) begin
            state <= 4'h2;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'h2: begin
          if (tick) begin
            state <= 4'h3;
            data  <= {data[6:0], 1'b1};
          end
        end
        4'h3: begin
          if (tick) begin
            state <= 4'h0;
            data  <= 8'h0;
            ready <= 1'b1;
          end
        end
        default: begin
          state <= 4'h0;
          data  <= 8'h0;
          ready <= 1'b0;
        end
      endcase
    end
  end
  assign io_ready = ready;
  assign tx = data[7];
endmodule

