module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] data;
reg [2:0] next_data;
reg [2:0] control;
reg [2:0] next_control;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= {3{1'b0}};
    end else begin
      data <= next_data;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      control <= {3{1'b0}};
    end else begin
      control <= next_control;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_data <= {3{1'b0}};
    end else begin
      if((WR == 1'b1)) begin
        next_data <= D;
      end
      else begin
        next_data <= data;
      end
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_control <= {3{1'b0}};
    end else begin
      if((RD == 1'b1)) begin
        next_control <= {3{1'b0}};
      end
      else begin
        next_control <= control;
      end
    end
  end
  assign WCTRL = (control[2] == 1'b1) ? 1'b1 : 1'b0;
  always @(data) begin
    case(data)
      3'b000 : Y <= 7'b0000001;
      3'b001 : Y <= 7'b0000010;
      3'b010 : Y <= 7'b0000100;
      3'b011 : Y <= 7'b0001000;
      3'b100 : Y <= 7'b0010000;
      3'b101 : Y <= 7'b0100000;
      3'b110 : Y <= 7'b1000000;
      3'b111 : Y <= 7'b0000000;
      default : Y <= 7'b0000000;
    endcase
  end
endmodule

