module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    reg parity;
    reg stop;
    reg ready;
    always @(posedge i_clock or negedge reset) begin
        if (!reset) begin
            counter <= 4'd0;
            scan_code <= 8'd0;
            ready <= 1'b0;
            parity <= 1'b0;
            stop <= 1'b0;
        end else begin
            if (counter == 4'd8) begin
                ready <= 1'b1;
                counter <= 4'd0;
            end else if (counter == 4'd9) begin
                if (i_data == 1'b0) begin
                    parity <= 1'b1;
                end else begin
                    parity <= 1'b0;
                end
                counter <= 4'd0;
            end else if (counter == 4'd10) begin
                if (i_data == 1'b1) begin
                    stop <= 1'b1;
                end else begin
                    stop <= 1'b0;
                end
                counter <= 4'd0;
            end else begin
                scan_code[counter] <= i_data;
                counter <= counter + 4'd1;
            end
        end
    end
    assign scan_ready = ready;
    assign scan_code = scan_code;
endmodule

