module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);
reg signed[41:0] a_r;
	reg signed[41:0] a_i;
	reg signed[41:0] b_r;
	reg signed[41:0] b_i;
	reg signed[41:0] w_r;
	reg signed[41:0] w_i;
	reg signed[41:0] op_r;
	reg signed[41:0] op_i;
	reg signed[41:0] delay_r;
	reg signed[41:0] delay_i;
	reg outvalid;
	always @(*) begin
		case(state)
			2'b00: begin
				op_r = 0;
				op_i = 0;
				delay_r = 0;
				delay_i = 0;
				outvalid = 0;
			end
			2'b01: begin
				op_r = a_r + b_r;
				op_i = a_i + b_i;
				delay_r = a_r - b_r;
				delay_i = a_i - b_i;
				outvalid = 1;
			end
			2'b10: begin
				op_r = a_r * w_r - a_i * w_i;
				op_i = a_r * w_i + a_i * w_r;
				delay_r = b_r * w_r - b_i * w_i;
				delay_i = b_r * w_i + b_i * w_r;
				outvalid = 1;
			end
			2'b11: begin
				op_r = 0;
				op_i = 0;
				delay_r = 0;
				delay_i = 0;
				outvalid = 0;
			end
		endcase
	end
	always @(din_a_r, din_a_i, din_b_r, din_b_i, w_r, w_i) begin
		a_r = din_a_r;
		a_i = din_a_i;
		b_r = din_b_r;
		b_i = din_b_i;
		w_r = w_r;
		w_i = w_i;
	end
endmodule

