module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;
reg          s_ready_t;
reg          m_valid_t;
reg  [1:0]   state;
reg  [1:0]   next_state;

assign s_ready = s_ready_t;
assign m_valid = m_valid_t;
assign m_data  = data_p1;

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
        s_ready_t <= 1'b0;
        m_valid_t <= 1'b0;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
    end
    else begin
        state <= next_state;
        s_ready_t <= state[0];
        m_valid_t <= state[1];
        load_p1 <= load_p1_from_p2;
        load_p2 <= load_p1;
        load_p1_from_p2 <= (state == ONE && s_valid && m_ready) ? 1'b1 : 1'b0;
    end
end

always @(*) begin
    case (state)
        ZERO: begin
            next_state = (s_valid && m_ready) ? ONE : ZERO;
        end
        ONE: begin
            next_state = (s_valid && m_ready) ? TWO : ZERO;
        end
        TWO: begin
            next_state = (s_valid && m_ready) ? ONE : ZERO;
        end
        default: begin
            next_state = ZERO;
        end
    endcase
end

always @(state, load_p1, data_p1, s_data) begin
    case (state)
        ZERO: begin
            data_p1 <= 'h0;
        end
        ONE: begin
            data_p1 <= data_p2;
        end
        TWO: begin
            data_p1 <= s_data;
        end
        default: begin
            data_p1 <= 'h0;
        end
    endcase
end

endmodule

