module contador8bits(
input wire reset,
input wire clk,
input wire mode,
output reg [7:0] Q
);
reg [7:0] contador;
  always @(posedge reset, posedge clk) begin
    if(reset == 1'b1) begin
      contador <= 8'b00000000;
    end else begin
      if(mode == 1'b1) begin
        contador <= contador + 1;
      end
      else begin
        contador <= contador - 1;
      end
    end
  end
  assign Q = contador;
endmodule

