module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [64*16-1:0] datainmem;
reg [64*16-1:0] dataoutmem;
reg [64*16-1:0] datamem[0:64*16-1];

always @(posedge clk) begin
    if (rst) begin
        datainmem <= 64*16'b0;
        dataoutmem <= 64*16'b0;
        datamem <= 64*16'b0;
    end
    else begin
        if (wren) begin
            datamem[address1] <= datain[64*16-1:64*16-inputsize];
            datamem[address1+1] <= datain[64*16-inputsize-1:0];
        end
        if (rden) begin
            dataoutmem <= datamem[address2+inputsize-1:address2];
        end
    end
end

assign dataout = dataoutmem[16*16-1:16*16-inputsize];

endmodule

