module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

    reg [DATA_BITS-1:0] mem [DEPTH-1:0];
    reg [DEPTH_BITS-1:0] index;
    reg empty;
    reg full;

    assign empty_n = ~empty;
    assign full_n  = ~full;

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= {DEPTH_BITS{1'b0}};
        end
        else begin
            if (write) begin
                if (empty) begin
                    empty <= 1'b0;
                    full <= 1'b0;
                end
                mem[index] <= din;
                index <= index + 1'b1;
                if (index == DEPTH-1) begin
                    full <= 1'b1;
                end
            end
            if (read) begin
                if (full) begin
                    empty <= 1'b1;
                    full <= 1'b0;
                end
                index <= index - 1'b1;
                if (index == 0) begin
                    empty <= 1'b0;
                end
            end
        end
    end

    assign dout = mem[index];

endmodule

