module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter PERIOD = 8;
reg [31:0] duty_reg;
reg [31:0] counter;
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      duty_reg <= duty;
      counter <= 0;
      pwm_out <= 1'b0;
    end
    else begin
      if(counter < duty_reg) begin
        pwm_out <= 1'b1;
      end
      else begin
        pwm_out <= 1'b0;
      end
      if(counter == (PERIOD - 1)) begin
        counter <= 0;
        duty_reg <= duty;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

module KeyEncoder(Columns, Rows, Clock, Reset, OnesDigit, TensDigit, Found);
	input [3:0] Columns;
	input [3:0] Rows;
	input Clock, Reset;
	output reg [3:0] OnesDigit;
	output reg [3:0] TensDigit;
	output reg Found;
parameter [8:0] KeyMap = 9'b000000000;
	parameter [8:0] KeyMap0 = 9'b000000001;
	parameter [8:0] KeyMap1 = 9'b000000010;
	parameter [8:0] KeyMap2 = 9'b000000100;
	parameter [8:0] KeyMap3 = 9'b000001000;
	parameter [8:0] KeyMap4 = 9'b000010000;
	parameter [8:0] KeyMap5 = 9'b000100000;
	parameter [8:0] KeyMap6 = 9'b001000000;
	parameter [8:0] KeyMap7 = 9'b010000000;
	parameter [8:0] KeyMap8 = 9'b100000000;
	always @(posedge Clock) begin
		if (Reset) begin
			Found <= 0;
			OnesDigit <= 0;
			TensDigit <= 0;
		end
		else begin
			case (KeyMap)
				KeyMap0: begin
					Found <= 1;
					OnesDigit <= 0;
					TensDigit <= 0;
				end
				KeyMap1: begin
					Found <= 1;
					OnesDigit <= 1;
					TensDigit <= 0;
				end
				KeyMap2: begin
					Found <= 1;
					OnesDigit <= 2;
					TensDigit <= 0;
				end
				KeyMap3: begin
					Found <= 1;
					OnesDigit <= 3;
					TensDigit <= 0;
				end
				KeyMap4: begin
					Found <= 1;
					OnesDigit <= 4;
					TensDigit <= 0;
				end
				KeyMap5: begin
					Found <= 1;
					OnesDigit <= 5;
					TensDigit <= 0;
				end
				KeyMap6: begin
					Found <= 1;
					OnesDigit <= 6;
					TensDigit <= 0;
				end
				KeyMap7: begin
					Found <= 1;
					OnesDigit <= 7;
					TensDigit <= 0;
				end
				KeyMap8: begin
					Found <= 1;
					OnesDigit <= 8;
					TensDigit <= 0;
				end
				KeyMap9: begin
					Found <= 1;
					OnesDigit <= 9;
					TensDigit <= 0;
				end
				default: begin
					Found <= 0;
					OnesDigit <= 0;
					TensDigit <= 0;
				end
			endcase
		end
