  reg signed [IN_WIDTH-1:0] ad_reg;
  reg signed [COEFF_WIDTH-1:0] m_reg;
  reg signed [ACCUM_WIDTH-1:0] p_reg;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end
    else if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
