module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);
reg		[Q_WIDTH-1:0]	r_q_P	[LATENCY:0];
reg		[A_WIDTH-1:0]	r_a_1P;
reg		[B_WIDTH-1:0]	r_b_1P;

assign	o = r_q_P[LATENCY];

always @(posedge clk or negedge arst)
begin
	if(!arst)
	begin
		r_a_1P	<= 'b0;
		r_b_1P	<= 'b0;
		r_q_P	<= 'b0;
	end
	else
	begin
		r_a_1P	<= a;
		r_b_1P	<= b;
		r_q_P	<= {r_q_P[LATENCY-1:0], r_a_1P * r_b_1P};
	end
end

endmodule

module sparc_ifu_sscan(
    input wire [10:0] swl_sscan_thrstate,
    input wire [3:0] ifq_sscan_test_data,
    input wire [15:0] lsu_sscan_test_data,
    input wire [62:0] tlu_sscan_test_data,
    input wire rclk,


    output reg [94-1:0] core_rtap_data,
    input wire rtap_core_val,
    input wire [1:0] rtap_core_threadid,
    input wire [4-1:0]  rtap_core_id,
    input wire [94-1:0] rtap_core_data

    );
reg [94-1:0] snap_data;
    reg [94-1:0] snap_data_next;
    reg rtap_sscan_snap;
    reg rtap_sscan_snap_f;

    always @(posedge rclk) begin
        if (rtap_core_val && rtap_core_id == 5) begin
            snap_data_next <= {swl_sscan_thrstate, ifq_sscan_test_data, lsu_sscan_test_data, tlu_sscan_test_data};
        end
        else begin
            snap_data_next <= snap_data;
        end
        if (rtap_core_val && rtap_core_id == 5) begin
            rtap_sscan_snap <= 1'b1;
        end
        else begin
            rtap_sscan_snap <= 1'b0;
        end
        if (rtap_sscan_snap) begin
            rtap_sscan_snap_f <= 1'b1;
        end
        else begin
            rtap_sscan_snap_f <= 1'b0;
        end
        if (rtap_sscan_snap_f) begin
            snap_data <= snap_data_next;
        end
        else begin
            snap_data <= snap_data;
        end
    end

    assign core_rtap_data = snap_data;

endmodule

