        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @(state, s_valid, m_ready) begin
    case (state)
        ZERO: begin
            if (s_valid) begin
                next_state <= ONE;
            end else begin
                next_state <= ZERO;
            end
        end
        ONE: begin
            if (m_ready) begin
                next_state <= TWO;
            end else begin
                next_state <= ONE;
            end
        end
        TWO: begin
            if (s_valid) begin
                next_state <= ONE;
            end else begin
                next_state <= TWO;
            end
        end
        default: begin
            next_state <= ZERO;
        end
    endcase
end

always @(state, s_valid, m_ready) begin
    case (state)
        ZERO: begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            s_ready_reg <= 1'b0;
            m_valid_reg <= 1'b0;
        end
        ONE: begin
            load_p1 <= 1'b1;
            load_p2 <= 1'b0;
            s_ready_reg <= 1'b1;
            m_valid_reg <= 1'b0;
        end
        TWO: begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b1;
            s_ready_reg <= 1'b0;
            m_valid_reg <= 1'b1;
        end
        default: begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            s_ready_reg <= 1'b0;
            m_valid_reg <= 1'b0;
        end
    endcase
end

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= data_p1;
    end
end

always @(posedge clk) begin
    if (load) begin
        load <= 1'b0;
    end else if (state == ONE && m_ready) begin
        load <= 1'b1;
    end
end

endmodule

