module sbox(
	output [7:0] SubByte,
	input [7:0] num
	);
wire [7:0] y, t, z, tc;
	assign y = num ^ 8'b10000000;
	assign t = y ^ 8'b01100000;
	assign z = t ^ 8'b00010000;
	assign tc = z ^ 8'b00000100;
	assign SubByte = tc ^ 8'b00000010;
endmodule

module minimal_modelb_rom_set (
    input            clk,
    input [17:0]     addr,
    output reg [7:0] data
);
reg [7:0] rom0 [0:16383];
    reg [7:0] rom1 [0:16383];
    reg [7:0] rom2 [0:16383];

    initial begin
        $readmemh("./rom_set/rom0.dat", rom0);
        $readmemh("./rom_set/rom1.dat", rom1);
        $readmemh("./rom_set/rom2.dat", rom2);
    end

    always @(posedge clk) begin
        case (addr[17:14])
            4'b0000: data <= rom0[addr[13:0]];
            4'b0001: data <= rom1[addr[13:0]];
            4'b0010: data <= rom2[addr[13:0]];
            default: data <= 8'h00;
        endcase
    end

endmodule

