        4'b0011: result = a | b;
        4'b0100: result = ~(a & b);
        4'b0101: result = a ^ b;
        4'b0110: result = a < b ? 1 : 0;
        4'b0111: result = a >> b;
        4'b1000: result = a << b;
        default: result = a + b;
    endcase
    zero = result == 0;
end
