module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg [15:0] Pout_de_w;
    reg [15:0] Pout_hs_w;
    reg [15:0] Pout_vs_w;
    reg [15:0] Rden_w;
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
        end
        else begin
            if (V_cnt == I_v_total) begin
                V_cnt <= 0;
            end
            else begin
                V_cnt <= V_cnt + 1;
            end
            if (H_cnt == I_h_total) begin
                H_cnt <= 0;
            end
            else begin
                H_cnt <= H_cnt + 1;
            end
        end
    end
    assign Pout_de_w = (H_cnt < I_h_bporch) ? 0 : (H_cnt < I_h_sync) ? 1 : (H_cnt < I_h_res) ? 1 : 0;
    assign Pout_hs_w = (H_cnt < I_h_sync) ? 0 : (H_cnt < I_h_total) ? 1 : 0;
    assign Pout_vs_w = (V_cnt < I_v_bporch) ? 0 : (V_cnt < I_v_sync) ? 1 : (V_cnt < I_v_total) ? 1 : 0;
    assign Rden_w = (H_cnt < I_rd_hres) ? 1 : 0;
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_rden <= 0;
            O_de   <= 0;
            O_hs   <= 0;
            O_vs   <= 0;
        end
        else begin
            O_rden <= Rden_w;
            O_de   <= Pout_de_w;
            O_hs   <= Pout_hs_w;
            O_vs   <= Pout_vs_w;
        end
    end
    assign O_hs = I_hs_pol ? ~Pout_hs_w : Pout_hs_w;
    assign O_vs = I_vs_pol ? ~Pout_vs_w : Pout_vs_w;
endmodule

