module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem [DEPTH-1:0];
    reg [DEPTH_BITS-1:0] index;
    reg empty;
    reg full;
    assign empty_n = ~empty;
    assign full_n = ~full;
    assign dout = mem[index];
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            empty <= 1;
            full <= 0;
            index <= 0;
        end
        else begin
            if (write) begin
                if (empty) begin
                    empty <= 0;
                    full <= 1;
                end
                else begin
                    index <= index + 1;
                    if (index == DEPTH-1) begin
                        index <= 0;
                    end
                end
            end
            else if (read) begin
                if (full) begin
                    full <= 0;
                    empty <= 1;
                end
                else begin
                    index <= index - 1;
                    if (index == 0) begin
                        index <= DEPTH-1;
                    end
                end
            end
        end
    end
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            mem <= {DEPTH{1'b0}};
        end
        else begin
            if (write) begin
                mem[index] <= din;
            end
        end
    end
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always@(posedge clk)
begin
if(timer<1000000)
begin
timer=timer+1;
end
else
begin
if(btn_input==pre)
begin
btn_output=btn_input;
pre=btn_input;
timer=0;
end
end
end
endmodule

