module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0] last_fib;
reg [7:0] last_last_fib;
always @(posedge CLK_IN or negedge RST_N) begin
    if (!RST_N) begin
        last_fib <= 0;
        last_last_fib <= 0;
    end
    else begin
        last_last_fib <= last_fib;
        last_fib <= last_last_fib + last_fib;
    end
end
assign SEQUENCE = last_fib;
endmodule

