module memory(clk, reset, data_op, instruct_addr, data_addr, write_val, instruct_val, read_val); 

  input wire clk;	                   
  input wire reset;
  input wire data_op;
  input wire [31:0]  instruct_addr;               
  input wire [31:0]  data_addr;               
  input wire [31:0] write_val;

  output reg [31:0] instruct_val;
  output reg[31:0] read_val;
reg [31:0] memory [0:511];
  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      instruct_val = 0;
      read_val = 0;
      for (int i = 0; i < 11; i = i + 1) begin
        memory[i] = 5;
      end
    end
    else begin
      instruct_val = memory[instruct_addr];
      if (data_op == 1) begin
        read_val = memory[data_addr];
      end
      else begin
        memory[data_addr] = write_val;
      end
    end
  end
endmodule

