module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter		Divider = 100000;
reg [26:0]	Counter;
always @(posedge Clock)
begin
	Timeout = (Counter >= Divider) ? 1 : 0;
end
always @(posedge Clock or posedge MR)
begin
	if (MR)
		Counter <= 0;
	else if (Counter >= Divider)
		Counter <= 0;
	else
		Counter <= Counter + 1;
end
endmodule

