module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;
reg          s_ready_reg;
reg  [1:0]   state;
reg  [1:0]   next_state;

assign s_ready = s_ready_reg;
assign m_data  = data_p1;
assign m_valid = (state == ONE) || (state == TWO);

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @(state, s_valid, s_ready, m_ready) begin
    {load_p1, load_p2, load_p1_from_p2, s_ready_reg, next_state} = 5'b0;
    case (state)
        ZERO: begin
            if (s_valid && s_ready && m_ready) begin
                load_p1_from_p2 <= 1'b1;
                load_p1         <= 1'b1;
                s_ready_reg     <= 1'b0;
                next_state      <= ONE;
            end
        end
        ONE: begin
            if (s_valid && s_ready && m_ready) begin
                load_p1         <= 1'b1;
                s_ready_reg     <= 1'b0;
                next_state      <= TWO;
            end
        end
        TWO: begin
            if (s_valid && s_ready && m_ready) begin
                load_p1         <= 1'b1;
                s_ready_reg     <= 1'b0;
                next_state      <= ONE;
            end
        end
    endcase
end

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
    if (load_p2) begin
        data_p2 <= data_p1;
    end
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;

assign dout = counter;

parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE:
            begin
                if(mode)
                begin
                    counter <= din + 1;
                    state <= INC_STATE;
                end
                else
                begin
                    counter <= din + 2;
                    state <= INC_STATE;
                end
            end
            INC_STATE:
            begin
                if(mode)
                begin
                    counter <= counter + 1;
                end
                else
                begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
            end
        endcase
    end
end

endmodule

