module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);
(* ram_style = "block" *) reg [31:0] ram [0:511]; 
  reg [8:0] value; 
  reg [8:0] value_1; 
  reg maybe_full; 
  assign io_enq_ready = ~maybe_full; 
  assign io_deq_valid = (value_1 != 9'h0); 
  assign io_deq_bits = ram[value_1]; 
  always @(posedge clock) begin 
    if (reset) begin 
      value <= 9'h0; 
      value_1 <= 9'h0; 
      maybe_full <= 1'b0; 
    end 
    else begin 
      if (io_enq_valid) begin 
        ram[value] <= io_enq_bits; 
        value <= value + 9'h1; 
        if (value == 9'h200) begin 
          value <= 9'h0; 
          maybe_full <= 1'b1; 
        end 
      end 
      if (io_deq_ready) begin 
        value_1 <= value_1 + 9'h1; 
        if (value_1 == 9'h200) begin 
          value_1 <= 9'h0; 
        end 
      end 
      if (maybe_full) begin 
        if (value == 9'h1ff) begin 
          maybe_full <= 1'b0; 
        end 
      end 
    end 
  end 
endmodule

