module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,
    output reg          lfsr_out_f
);
localparam TAPS = 16'h0001;
    localparam WIDTH = 16;

    reg [WIDTH-1:0] lfsr_state;
    reg [WIDTH-1:0] lfsr_next;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state <= 0;
        end else if (lfsr_ld) begin
            lfsr_state <= lfsr_seed;
        end else if (lfsr_step) begin
            lfsr_state <= lfsr_next;
        end
    end

    always @(*) begin
        lfsr_next = lfsr_state;
        lfsr_next[WIDTH-1] = lfsr_state[WIDTH-1] ^ lfsr_state[WIDTH-2] ^ lfsr_state[WIDTH-3] ^ lfsr_state[WIDTH-4] ^ lfsr_state[WIDTH-5] ^ lfsr_state[WIDTH-6] ^ lfsr_state[WIDTH-7] ^ lfsr_state[WIDTH-8] ^ lfsr_state[WIDTH-9] ^ lfsr_state[WIDTH-10] ^ lfsr_state[WIDTH-11] ^ lfsr_state[WIDTH-12] ^ lfsr_state[WIDTH-13] ^ lfsr_state[WIDTH-14] ^ lfsr_state[WIDTH-15];
    end

    assign lfsr_out_f = lfsr_state[WIDTH-1];

    assign lfsr_state_f = lfsr_state;

endmodule

module mux4_1n (
    input EN_n,
    input A, B,
    input D0, D1, D2, D3,
    output Y
);
reg Y_reg;
    wire [1:0] S;
    assign S = {A, B};
    always @(EN_n, S, D0, D1, D2, D3) begin
        case (S)
            2'b00: Y_reg <= D0;
            2'b01: Y_reg <= D1;
            2'b10: Y_reg <= D2;
            2'b11: Y_reg <= D3;
        endcase
    end
    assign Y = EN_n ? 1'b0 : Y_reg;
endmodule

