module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
    );
reg [3:0] step_count = 0;
    always @(posedge sysclk) begin
        if (anodes != 8'b00000000) begin
            if (step_count == 0) begin
                data <= anodes[0];
                shift <= 1;
                step_count <= 1;
            end
            else if (step_count == 1) begin
                data <= anodes[1];
                shift <= 1;
                step_count <= 2;
            end
            else if (step_count == 2) begin
                data <= anodes[2];
                shift <= 1;
                step_count <= 3;
            end
            else if (step_count == 3) begin
                data <= anodes[3];
                shift <= 1;
                step_count <= 4;
            end
            else if (step_count == 4) begin
                data <= anodes[4];
                shift <= 1;
                step_count <= 5;
            end
            else if (step_count == 5) begin
                data <= anodes[5];
                shift <= 1;
                step_count <= 6;
            end
            else if (step_count == 6) begin
                data <= anodes[6];
                shift <= 1;
                step_count <= 7;
            end
            else if (step_count == 7) begin
                data <= anodes[7];
                shift <= 1;
                step_count <= 8;
            end
            else if (step_count == 8) begin
                data <= 0;
                shift <= 0;
                latch <= 1;
                step_count <= 0;
            end
        end
        else begin
            data <= 0;
            shift <= 0;
            latch <= 0;
            step_count <= 0;
        end
    end
endmodule

