module leddec16(
input wire [1:0] dig,
input wire [15:0] data,
output wire [3:0] anode,
output wire [6:0] seg
); 

parameter [31:0] ROM_SIZE=4;
  wire [3:0] anode_tmp;
  wire [6:0] seg_tmp;
  wire [15:0] data_tmp;
  assign data_tmp = data;
  assign anode_tmp = {1'b0,anode[3:1]};
  assign seg_tmp = {1'b0,seg[6:0]};
  assign anode[0] = (data_tmp[15:12] != 4'b0000) | (data_tmp[11:8] != 4'b0000) | (data_tmp[7:4] != 4'b0000) | (data_tmp[3:0] != 4'b0000);
  assign anode[1] = (data_tmp[11:8] != 4'b0000) | (data_tmp[7:4] != 4'b0000) | (data_tmp[3:0] != 4'b0000);
  assign anode[2] = (data_tmp[7:4] != 4'b0000) | (data_tmp[3:0] != 4'b0000);
  assign anode[3] = (data_tmp[3:0] != 4'b0000);
  assign seg[0] = (dig == 2'b00) ? seg_tmp[0] : 1'b0;
  assign seg[1] = (dig == 2'b01) ? seg_tmp[1] : 1'b0;
  assign seg[2] = (dig == 2'b10) ? seg_tmp[2] : 1'b0;
  assign seg[3] = (dig == 2'b11) ? seg_tmp[3] : 1'b0;
  assign seg[4] = (dig == 2'b00) ? seg_tmp[4] : 1'b0;
  assign seg[5] = (dig == 2'b01) ? seg_tmp[5] : 1'b0;
  assign seg[6] = (dig == 2'b10) ? seg_tmp[6] : 1'b0;
endmodule

