module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [DATA_WIDTH-1:0]mem [FIFO_DEPTH-1:0];
reg [clog2_FIFO_DEPTH:0]wrptr,rdptr;
reg wrreq_int,rdreq_int;

assign data_out = mem[rdptr];

assign empty = (rdptr == wrptr);
assign full = (rdptr == (wrptr + 1));

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
    end
    else
    begin
        if(wrreq_int)
        begin
            if(wrptr == (FIFO_DEPTH - 1))
                wrptr <= 0;
            else
                wrptr <= wrptr + 1;
        end
        if(rdreq_int)
        begin
            if(rdptr == (FIFO_DEPTH - 1))
                rdptr <= 0;
            else
                rdptr <= rdptr + 1;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrreq_int <= 0;
        rdreq_int <= 0;
    end
    else
    begin
        wrreq_int <= wrreq & ~empty;
        rdreq_int <= rdreq & ~full;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        usedw <= 0;
    end
    else
    begin
        if(wrreq_int)
            usedw <= usedw + 1;
        if(rdreq_int)
            usedw <= usedw - 1;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        mem <= 0;
    end
    else
    begin
        if(wrreq_int)
            mem[wrptr] <= data_in;
    end
end

endmodule

