  reg [31:0] M_x;
  reg [31:0] M_y;
  reg [31:0] M_z;
  reg [31:0] M_w;
  reg [31:0] M_w_d;

  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= 32'h00000001;
      M_w_d <= {32'h00000001, seed};
    end else if (next) begin
      M_x <= M_y;
      M_y <= M_z;
      M_z <= M_w;
      M_w <= M_w_d;
    end
  end

  wire [31:0] t = M_x[31:0] ^ M_x[23:0] ^ M_x[15:0] ^ M_x[7:0] ^ M_x[3:0] ^ M_x[1:0];

  always @(posedge clk) begin
    M_w_d <= {t, M_w[31:1]};
  end

  assign num = M_w[31:0];

endmodule

