module clock_divider(
input wire clock,
output wire clock_div
); 

parameter [31:0] input_frequency=100000000;
parameter [31:0] output_frequency=1000000;
reg [31:0] counter = 0;
reg clock_signal = 1'b0;
  always @(posedge clock) begin
    if((counter < (input_frequency / output_frequency))) begin
      counter <= counter + 1;
    end
    else begin
      counter <= 0;
      clock_signal <=  ~clock_signal;
    end
  end
  assign clock_div = clock_signal;
endmodule

module cycloneiv_pciehip_pciexp_dcfiforam (data, wren, wraddress, rdaddress, wrclock, rdclock, q);
   input[data_width - 1:0] data; 
   input wren; 
   input[addr_width - 1:0] wraddress; 
   input[addr_width - 1:0] rdaddress; 
   input wrclock; 
   input rdclock; 
   output[data_width - 1:0] q;
parameter MEM_SIZE = 256;
   parameter MEM_TYPE = "block";
   parameter DATA_WIDTH = 32;
   parameter ADDR_WIDTH = 8;
   reg[DATA_WIDTH - 1:0] mem[0:MEM_SIZE - 1];
   reg[ADDR_WIDTH - 1:0] rdaddress_reg;
   reg[ADDR_WIDTH - 1:0] wraddress_reg;
   reg wren_reg;
   reg[DATA_WIDTH - 1:0] data_reg;
   assign q = mem[rdaddress_reg];
   always @(posedge wrclock) begin
      if (wren) begin
         mem[wraddress_reg] <= data_reg;
      end
      wren_reg <= wren;
      wraddress_reg <= wraddress;
      data_reg <= data;
   end
   always @(posedge rdclock) begin
      rdaddress_reg <= rdaddress;
   end
endmodule

