module adder_word(	input wire [31:0] a,
			input wire [31:0] b,
			input wire carry_in,
			output wire [31:0] sum,
			output wire carry_out);
wire tmp_carry;
	assign sum[7:0] = a[7:0] + b[7:0] + carry_in;
	assign tmp_carry = sum[7] ^ carry_in;
	assign sum[15:8] = a[15:8] + b[15:8] + tmp_carry;
	assign tmp_carry = sum[15] ^ tmp_carry;
	assign sum[23:16] = a[23:16] + b[23:16] + tmp_carry;
	assign tmp_carry = sum[23] ^ tmp_carry;
	assign sum[31:24] = a[31:24] + b[31:24] + tmp_carry;
	assign carry_out = sum[31];
endmodule

