module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
parameter BAUD_RATE = 9600;
    parameter PERIOD = 100000000 / BAUD_RATE;
    parameter BIT_PERIOD = PERIOD / 8;
    parameter START_BIT = 1;
    parameter DATA_BITS = 8;
    parameter PARITY_BIT = 1;
    parameter STOP_BIT = 1;
    parameter TOTAL_BITS = START_BIT + DATA_BITS + PARITY_BIT + STOP_BIT;
    parameter STATE_IDLE = 0;
    parameter STATE_START_BIT = 1;
    parameter STATE_DATA_BITS = 2;
    parameter STATE_PARITY_BIT = 3;
    parameter STATE_STOP_BIT = 4;
    reg [3:0] state;
    reg [3:0] next_state;
    reg [3:0] bit_counter;
    reg [3:0] next_bit_counter;
    reg [7:0] shift_reg;
    reg [7:0] next_shift_reg;
    reg parity;
    reg next_parity;
    reg done_reg;
    reg next_done_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
            bit_counter <= 0;
            shift_reg <= 0;
            parity <= 0;
            done_reg <= 0;
        end else begin
            state <= next_state;
            bit_counter <= next_bit_counter;
            shift_reg <= next_shift_reg;
            parity <= next_parity;
            done_reg <= next_done_reg;
        end
    end
    always @(*) begin
        next_state = state;
        next_bit_counter = bit_counter;
        next_shift_reg = shift_reg;
        next_parity = parity;
        next_done_reg = done_reg;
        case (state)
            STATE_IDLE: begin
                if (start) begin
                    next_state = STATE_START_BIT;
                    next_bit_counter = 0;
                    next_shift_reg = {1'b0, data_in};
                    next_parity = 0;
                    next_done_reg = 0;
                end
            end
            STATE_START_BIT: begin
                if (bit_counter == BIT_PERIOD) begin
                    next_state = STATE_DATA_BITS;
                    next_bit_counter = 0;
                    next_shift_reg = {1'b0, data_in};
                    next_parity = 0;
                    next_done_reg = 0;
                end
            end
            STATE_DATA_BITS: begin
                if (bit_counter == BIT_PERIOD) begin
                    next_bit_counter = 0;
                    next_shift_reg = {shift_reg[6:0], 1'b0};
                    next_parity = next_parity ^ shift_reg[7];
                    if (bit_counter == BIT_PERIOD * (DATA_BITS - 1)) begin
                        next_state = STATE_PARITY_BIT;
                    end
                end
            end
            STATE_PARITY_BIT: begin
                if (bit_counter == BIT_PERIOD) begin
                    next_bit_counter = 0;
                    next_shift_reg = {shift_reg[6:0], 1'b0};
                    next_parity = next_parity ^ shift_reg[7];
                    if (bit_counter == BIT_PERIOD * (PARITY_BIT - 1)) begin
                        next_state = STATE_STOP_BIT;
                    end
                end
            end
            STATE_STOP_BIT: begin
                if (bit_counter == BIT_PERIOD) begin
                    next_bit_counter = 0;
                    next_shift_reg = {shift_reg[6:0], 1'b0};
                    next_parity = next_parity ^ shift_reg[7];
                    if (bit_counter == BIT_PERIOD * (STOP_BIT - 1)) begin
                        next_state = STATE_IDLE;
                        next_done_reg = 1;
                    end
                end
            end
        endcase
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            data_out <= shift_reg[7:0];
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
        end else begin
            done <= done_reg;
        end
    end
endmodule

module muladd_3_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);
logic signed [15:0] stage0;
	logic signed [15:0] stage1;
	logic signed [15:0] stage2;

	always @(posedge clk) begin
	stage0 <= (a * b) + c;
	stage1 <= stage0;
	stage2 <= stage1;
	end

	assign out = stage2;
endmodule

