  reg iowr_reg;
  reg iordwr_reg;
  reg memrd_reg;
  reg memwr_reg;
  reg memrw_reg;
  reg opfetch_reg;
  reg intack_reg;
  always @(posedge clk) begin
    if (zpos) begin
      iorq_reg <= iorq_n;
      mreq_reg <= mreq_n;
    end
    else begin
      iorq_reg <= iorq_reg_s;
      mreq_reg <= mreq_reg_s;
    end
  end
  always @(posedge clk) begin
    iorq_reg_s <= iorq_reg;
    mreq_reg_s <= mreq_reg;
  end
  always @(posedge clk) begin
    iord_reg <= rd_n;
    iowr_reg <= wr_n;
    iordwr_reg <= rd_n & wr_n;
    memrd_reg <= m1_n & rd_n;
    memwr_reg <= m1_n & wr_n;
    memrw_reg <= m1_n & rd_n & wr_n;
    opfetch_reg <= rd_n & m1_n;
    intack_reg <= rd_n & m1_n;
  end
  assign rst = rst_n;
  assign m1 = m1_n;
  assign rfsh = rfsh_n;
  assign rd = rd_n;
  assign wr = wr_n;
  assign iorq = iorq_n;
  assign mreq = mreq_n;
  assign rdwr = rd_n & wr_n;
  assign iord = iord_reg;
  assign iowr = iowr_reg;
  assign iordwr = iordwr_reg;
  assign memrd = memrd_reg;
  assign memwr = memwr_reg;
  assign memrw = memrw_reg;
  assign opfetch = opfetch_reg;
  assign intack = intack_reg;
  assign iorq_s = iorq_reg_s;
  assign mreq_s = mreq_reg_s;
  assign iord_s = iord_reg;
  assign iowr_s = iowr_reg;
  assign iordwr_s = iordwr_reg;
  assign memrd_s = memrd_reg;
  assign memwr_s = memwr_reg;
  assign memrw_s = memrw_reg;
  assign opfetch_s = opfetch_reg;
endmodule

