module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(*) begin
    case (alu_ctrl)
        4'b0000: result = x + y;
        4'b0001: result = x - y;
        4'b0010: result = x * y;
        4'b0011: result = x / y;
        4'b0100: result = x & y;
        4'b0101: result = x | y;
        4'b0110: result = x ^ y;
        4'b0111: result = x < y;
        default: result = 0;
    endcase
    zero = (result == 0);
end
endmodule

