module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 2'b00, 
          SETUP = 2'b01, 
          ACCESS = 2'b10;

reg [1:0] state, next_state;
reg [1:0] state_next;

always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
        state <= IDLE;
    end else begin
        state <= state_next;
    end
end

always @(state, Transfer, PREADY, PSLVERR) begin
    case (state)
        IDLE: begin
            if (Transfer) begin
                state_next = SETUP;
            end else begin
                state_next = IDLE;
            end
        end
        SETUP: begin
            if (PREADY) begin
                PSELx = 1;
                PENABLE = 1;
                PWRITE = Wr_Rd;
                PADDR = Address;
                PWDATA = write_data;
                state_next = ACCESS;
            end else begin
                state_next = SETUP;
            end
        end
        ACCESS: begin
            if (PSLVERR) begin
                state_next = IDLE;
            end else if (PREADY) begin
                if (Wr_Rd) begin
                    read_data = PRDATA;
                end else begin
                    PWDATA = PRDATA;
                end
                state_next = IDLE;
            end else begin
                state_next = ACCESS;
            end
        end
        default: begin
            state_next = IDLE;
        end
    endcase
end

endmodule

