    parameter SPRITE_WIDTH = 16;
    parameter SPRITE_HEIGHT = 16;
    parameter NUM_SPRITES = 16;

    reg [3:0] rom [0:NUM_SPRITES*SPRITE_WIDTH*SPRITE_HEIGHT-1];

    initial begin
        $readmemb(BITMAP_FILE, rom);
    end

    always @(posedge clk) begin
        pixel <= rom[add];
    end

endmodule

module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] UpperBound = 28;
reg [27:0] counter = 0;
  always @(posedge clk) begin
    if((counter < UpperBound)) begin
      counter <= counter + 1;
    end
    else begin
      counter <= 0;
    end
  end
  assign pulse = (counter == UpperBound);
endmodule

