module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
parameter [1:0]
    IDLE = 2'b00,
    LOAD = 2'b01,
    TRIG = 2'b10,
    POLL = 2'b11;

    parameter MSG_DELAY = 100000000;

    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] data_pos;
    reg [31:0] delay;
    reg [31:0] next_delay;

    always @(posedge clk_50M) begin
        if (run_test_raw) begin
            state <= IDLE;
            data_pos <= 0;
            delay <= 0;
        end
        else begin
            state <= next_state;
            data_pos <= data_pos + 1;
            delay <= next_delay;
        end
    end

    always @(state, data_pos, tx_busy, delay) begin
        next_state <= state;
        next_delay <= delay;
        case (state)
            IDLE: begin
                if (run_test_raw) begin
                    next_state <= LOAD;
                    next_delay <= MSG_DELAY;
                end
            end
            LOAD: begin
                if (data_pos == 0) begin
                    next_state <= TRIG;
                    next_delay <= 0;
                end
                else begin
                    next_state <= LOAD;
                    next_delay <= 0;
                end
                data_out <= "Hello World! "[data_pos];
            end
            TRIG: begin
                if (tx_busy) begin
                    next_state <= TRIG;
                    next_delay <= 0;
                end
                else begin
                    next_state <= POLL;
                    next_delay <= 0;
                end
                trigger <= 1;
            end
            POLL: begin
                if (tx_busy) begin
                    next_state <= POLL;
                    next_delay <= 0;
                end
                else begin
                    next_state <= LOAD;
                    next_delay <= MSG_DELAY;
                end
                trigger <= 0;
            end
        endcase
    end
endmodule

