(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
reg [3:0]S, NS;
reg [7:0]in1, in2, in3, out;
