display_driver d1 (scan_code, HEX0);
display_driver d2 (out, HEX1);
always @(scan_code)
begin
	case (S)
		4'd0: begin
			if (scan_code[7] == 1'b1)
			begin
				in1 = scan_code;
				S = 4'd1;
			end
		end
		4'd1: begin
			if (scan_code[7] == 1'b1)
			begin
				in2 = scan_code;
				S = 4'd2;
			end
		end
		4'd2: begin
			if (scan_code[7] == 1'b1)
			begin
				in3 = scan_code;
				S = 4'd3;
			end
		end
		4'd3: begin
			if (scan_code[7] == 1'b1)
			begin
				out = in3;
				S = 4'd0;
			end
		end
	endcase
end
assign LEDR = {S, NS};
endmodule

