input irq;              
input [7:0] ir;         
input [2:0] alu_flags;     
output read, write, iack;                   
output [1:0] addr_sel, load_sel, count_sel; 
output count_up, top_enable, alu_enable;    
output [5:0] alu_op;
reg [3:0] ustate;
reg [21:0] ucode [0:255];
reg [5:0] nx_ustate;
initial begin
    $readmemh("microcode.hex", ucode);
    ustate = 4'b0000;
end
always @(posedge clk) begin
    if (reset) ustate <= 4'b0000;
    else ustate <= nx_ustate;
end
assign read = ucode[ustate][0];
assign write = ucode[ustate][1];
assign iack = ucode[ustate][2];
assign addr_sel = ucode[ustate][3:4];
assign load_sel = ucode[ustate][5:6];
assign count_sel = ucode[ustate][7:8];
assign count_up = ucode[ustate][9];
assign top_enable = ucode[ustate][10];
assign alu_enable = ucode[ustate][11];
assign alu_op = ucode[ustate][12:17];
assign nx_ustate = ucode[ustate][18:21] + 4'b0001;
endmodule

