module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
always @(posedge clk) begin
	if (startGameEn) begin
		x <= 0;
		y <= 0;
		colour <= 3'b000;
		end
	else begin
		if (x < 160 && y < 120) begin
			if (x == user_x && y == user_y) begin
				colour <= 3'b001;
			end
			else if (x == enemy_x && y == enemy_y) begin
				colour <= 3'b010;
			end
			else if (enem_grid[(y*160)+x] == 1) begin
				colour <= 3'b011;
			end
			else begin
				colour <= 3'b100;
			end
		end
		else begin
			x <= 0;
			y <= 0;
		end
		x <= x + 1;
		y <= y + 1;
	end
end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency=100000000;
parameter [31:0] g_Initial_Reset_Time=100000000;
parameter [31:0] c_Initial_Reset_Clocks = g_Clock_Frequency * g_Initial_Reset_Time;
reg r_RST;
reg [31:0] r_RST_Counter;
  always @(posedge i_CLK) begin
    if((r_RST == 1'b0)) begin
      r_RST_Counter <= 0;
      r_RST <= 1'b1;
    end
    else if((r_RST_Counter < c_Initial_Reset_Clocks)) begin
      r_RST_Counter <= r_RST_Counter + 1;
      r_RST <= 1'b1;
    end
    else begin
      r_RST <= 1'b0;
    end
  end
  assign o_RST = r_RST;
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
parameter standby = 0, startMeasure = 1, waitForPulse = 2, countPulse = 3;
reg [1:0] state = standby;
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
always @(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		state <= standby;
		READY <= 0;
		sonar_trigger <= 0;
		timeCount <= 0;
		timeoutCounter <= 0;
	end
	else begin
		case(state)
			standby: begin
				if(do_measure) begin
					state <= startMeasure;
					READY <= 1;
				end
				else begin
					state <= standby;
					READY <= 0;
				end
			end
			startMeasure: begin
				sonar_trigger <= 1;
				state <= waitForPulse;
			end
			waitForPulse: begin
				if(sonar_pulse) begin
					state <= countPulse;
				end
			end
			countPulse: begin
				if(!sonar_pulse) begin
					state <= standby;
					READY <= 0;
					timeoutCounter <= 0;
				end
				else begin
					timeoutCounter <= timeoutCounter + 1;
					if(timeoutCounter == 100000000) begin
						state <= standby;
						READY <= 0;
						timeoutCounter <= 0;
					end
					else begin
						timeCount <= timeCount + 1;
						inches <= timeCount / 100000000 * 147;
					end
				end
			end
		endcase
	end
end
endmodule

