module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
parameter Baud = 115200;
parameter Oversampling = 100000000 / Baud;

parameter log2 = $clog2(Oversampling);

reg [log2:0] Acc;
wire [log2:0] Inc = Acc + 1;

assign tick = Acc[log2];

always @(posedge clk) begin
	if (enable) begin
		if (Acc[log2]) begin
			Acc <= 0;
		end else begin
			Acc <= Inc;
		end
	end else begin
		Acc <= 0;
	end
end

endmodule

