module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);
if (LENGTH == 1) begin
        if (DELAT_STAGES == 0) begin
            assign out_sum = in_addends;
        end else begin
            reg signed [DATA_WIDTH-1:0] delay_reg;
            always @(posedge clk) begin
                if (rst) begin
                    delay_reg <= 0;
                end else begin
                    delay_reg <= in_addends;
                end
            end
            assign out_sum = delay_reg;
        end
    end else begin
        reg signed [DATA_WIDTH-1:0] delay_reg;
        always @(posedge clk) begin
            if (rst) begin
                delay_reg <= 0;
            end else begin
                delay_reg <= in_addends;
            end
        end
        wire signed [OUT_WIDTH-1:0] out_sum1;
        wire signed [OUT_WIDTH-1:0] out_sum2;
        AdderTreePipelined #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        ) adder1 (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(delay_reg[LENGTH*DATA_WIDTH-1:LENGTH*DATA_WIDTH/2]),
            .out_sum(out_sum1)
        );
        AdderTreePipelined #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        ) adder2 (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(delay_reg[LENGTH*DATA_WIDTH/2-1:0]),
            .out_sum(out_sum2)
        );
        assign out_sum = out_sum1 + out_sum2;
    end
endmodule

