module motor_rpm_count(
	input clk,
	input motor_rot_pulse,
	output wire [15:0]rpm_output
);
reg [31:0] pulse_count = 50000000 - 1;
	reg last_scan_value = 0;
	reg [15:0] pulse_count_qty = 0;
	reg [15:0] output_count_qty = 0;
	always @(posedge clk) begin
		if (pulse_count == 0) begin
			output_count_qty = pulse_count_qty;
			pulse_count = 50000000 - 1;
			pulse_count_qty = 0;
		end else begin
			if (motor_rot_pulse == 1'b1 && last_scan_value == 1'b0) begin
				pulse_count_qty = pulse_count_qty + 1;
			end
			pulse_count = pulse_count - 1;
			last_scan_value = motor_rot_pulse;
		end
	end
	assign rpm_output = output_count_qty;
