module top_flag_ethiopia #(parameter CORDW=10) (  
    input  wire logic clk_pix,             
    input  wire logic sim_rst,             
    output      logic [CORDW-1:0] sdl_sx,  
    output      logic [CORDW-1:0] sdl_sy,  
    output      logic sdl_de,              
    output      logic [7:0] sdl_r,         
    output      logic [7:0] sdl_g,         
    output      logic [7:0] sdl_b          
    );
logic [3:0] sy;
    always_comb begin
        if (sy < 160) begin
            sdl_r = 4'h0;
            sdl_g = 4'h0;
            sdl_b = 4'hF;
        end
        else if (sy < 320) begin
            sdl_r = 4'hF;
            sdl_g = 4'h0;
            sdl_b = 4'h0;
        end
        else begin
            sdl_r = 4'h0;
            sdl_g = 4'h0;
            sdl_b = 4'hF;
        end
    end
    simple_480p #(.CORDW(CORDW)) simple_480p_inst (
        .clk_pix(clk_pix),
        .sim_rst(sim_rst),
        .sdl_sx(sdl_sx),
        .sdl_sy(sdl_sy),
        .sdl_de(sdl_de)
    );
    always_ff @(posedge clk_pix) begin
        if (sim_rst) begin
            sdl_r <= 8'h0;
            sdl_g <= 8'h0;
            sdl_b <= 8'h0;
        end
        else begin
            sdl_r <= {sdl_r, sdl_r};
            sdl_g <= {sdl_g, sdl_g};
            sdl_b <= {sdl_b, sdl_b};
        end
    end
endmodule

