    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output[DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;
parameter MEM_STYLE = "shiftreg";
parameter DATA_WIDTH = 32'd1;
parameter ADDR_WIDTH = 32'd1;
parameter DEPTH = 32'd2;

wire[ADDR_WIDTH - 1:0] shiftReg_addr ;
wire[DATA_WIDTH - 1:0] shiftReg_data, shiftReg_q;
reg[ADDR_WIDTH:0] mOutPtr = {(ADDR_WIDTH+1){1'b0}};
reg internal_empty_n = 0, internal_full_n = 1;

assign if_empty_n = internal_empty_n;
assign if_full_n = internal_full_n;
assign shiftReg_data = if_din;
assign if_dout = shiftReg_q;

always @ (posedge clk) begin
    if (reset == 1'b1) begin
        mOutPtr <= {ADDR_WIDTH+1{1'b0}};
        internal_empty_n <= 1'b0;
        internal_full_n <= 1'b1;
    end
    else begin
        if (if_read_ce == 1'b1) begin
            if (mOutPtr == DEPTH[ADDR_WIDTH-1:0]) begin
                mOutPtr <= {ADDR_WIDTH+1{1'b0}};
            end
            else begin
                mOutPtr <= mOutPtr + 1[ADDR_WIDTH-1:0];
            end
            if (mOutPtr == {(ADDR_WIDTH){1'b0}}) begin
                internal_empty_n <= 1'b0;
            end
            else begin
                internal_empty_n <= internal_empty_n;
            end
        end
        if (if_write_ce == 1'b1) begin
            if (mOutPtr == {DEPTH[ADDR_WIDTH-1:0],1'b0}) begin
                mOutPtr <= {(ADDR_WIDTH){1'b0}};
            end
            else begin
                mOutPtr <= mOutPtr + 1[ADDR_WIDTH-1:0];
            end
            if (mOutPtr == DEPTH[ADDR_WIDTH-1:0]) begin
                internal_full_n <= 1'b0;
            end
            else begin
                internal_full_n <= internal_full_n;
            end
        end
        if ((if_read_ce == 1'b1) && (if_write_ce == 1'b0) && (internal_empty_n == 1'b1)) begin
            internal_empty_n <= 1'b0;
        end
        if ((if_read_ce == 1'b0) && (if_write_ce == 1'b1) && (internal_empty_n == 1'b0)) begin
            internal_empty_n <= 1'b1;
        end
        if ((if_read_ce == 1'b1) && (if_write_ce == 1'b0) && (internal_full_n == 1'b1)) begin
            internal_full_n <= 1'b0;
        end
        if ((if_read_ce == 1'b0) && (if_write_ce == 1'b1) && (internal_full_n == 1'b0)) begin
            internal_full_n <= 1'b1;
        end
    end
end

assign shiftReg_addr = mOutPtr[ADDR_WIDTH-1:0];

always @ (posedge clk) begin
    if (reset == 1'b1) begin
        shiftReg_data <= {DATA_WIDTH{1'b0}};
    end
    else begin
        if (if_write_ce == 1'b1) begin
            shiftReg_data <= if_din;
        end
    end
end

