module jtopl_div(
    input       rst,
    input       clk,
    input       cen,
    output reg  cenop   
);
parameter OPL_TYPE = 1;
    localparam W = 2;
    reg [W-1:0] cnt;
    always @(posedge clk) begin
        if (cen) begin
            cnt <= cnt + 1;
        end
    end
    assign cenop = cen & cnt;
endmodule

