module mem_gen3 (clk, addr, wr_ena, data);
input clk;
input [6:0] addr;
input wr_ena;
output [DATA_WIDTH-1:0] data;
parameter DATA_WIDTH = 12;

reg [DATA_WIDTH-1:0] data;

always @(posedge clk) begin
    case (addr)
        0: data <= 12'b000000000000;
        1: data <= 12'b000000000001;
        2: data <= 12'b000000000010;
        3: data <= 12'b000000000011;
        4: data <= 12'b000000000100;
        5: data <= 12'b000000000101;
        6: data <= 12'b000000000110;
        7: data <= 12'b000000000111;
        8: data <= 12'b000000001000;
        9: data <= 12'b000000001001;
        10: data <= 12'b000000001010;
        default: data <= 12'b000000000000;
    endcase
end

endmodule

module validation(
input wire [10:0] timeIn,
output wire valid
); 

wire [10:0] timeInWire;
wire outBit;
  assign timeInWire = timeIn;
  assign outBit = timeInWire < 11'b00000000000 ? 1'b1 : 1'b0;
  assign valid = outBit;
endmodule

