      32'b00000000000000000000000000000010 : O_RMotor <= WriteData;
      32'b00000000000000000000000000000011 : O_Buzzer <= WriteData;
      32'b00000000000000000000000000000100 : O_Seg <= WriteData;
      32'b00000000000000000000000000000101 : O_El_7l <= WriteData;
      default : ReadData <= 32'b00000000000000000000000000000000;
      endcase
    end
  end
