module zmc2_dot(
	input CLK_12M,
	input EVEN,
	input LOAD,
	input H,
	input [31:0] CR,
	output reg [3:0] GAD, GBD,
	output reg DOTA, DOTB
);
reg [31:0] SR;
	always @(negedge CLK_12M) begin
		if (LOAD) SR <= CR;
		if (H) begin
			SR[31:28] <= SR[27:24];
			SR[27:24] <= SR[23:20];
			SR[23:20] <= SR[19:16];
			SR[19:16] <= SR[15:12];
			SR[15:12] <= SR[11:8];
			SR[11:8] <= SR[7:4];
			SR[7:4] <= SR[3:0];
			SR[3:0] <= SR[31:28];
		end else begin
			SR[31:28] <= SR[27:24];
			SR[27:24] <= SR[23:20];
			SR[23:20] <= SR[19:16];
			SR[19:16] <= SR[15:12];
			SR[15:12] <= SR[11:8];
			SR[11:8] <= SR[7:4];
			SR[7:4] <= SR[3:0];
			SR[3:0] <= SR[31:28];
		end
	end
	assign GAD = {SR[27:24], SR[23:20], SR[19:16], SR[15:12]};
	assign GBD = {SR[27:24], SR[23:20], SR[19:16], SR[15:12]};
	assign DOTA = EVEN ? GAD[0] | GAD[1] : GAD[0] | GAD[1] | GAD[2] | GAD[3];
	assign DOTB = EVEN ? GBD[0] | GBD[1] : GBD[0] | GBD[1] | GBD[2] | GBD[3];
endmodule

