module bufferDatapointMemoryAccess(
  input         clock,
  input         reset,
  input         io_wrEna,
  input  [9:0]  io_Addr,
  input  [15:0] io_dataIn,
  output [15:0] io_rdData
);
(* ram_style = "block" *) reg [15:0] mem [0:1023];
  wire [15:0] rdData;
  assign io_rdData = rdData;
  assign rdData = io_wrEna ? 16'h0 : mem[io_Addr];
  always @(posedge clock) begin
    if (io_wrEna) begin
      mem[io_Addr] <= io_dataIn;
    end
  end
endmodule

module PC #(parameter WIDTH=8)
    (
    input clk,
    input reset,
    input [WIDTH-1:0] newpc,
    output reg [WIDTH-1:0] pc
    );
always @(posedge clk, posedge reset)
    begin
        if (reset)
            pc <= 0;
        else
            pc <= newpc;
    end
endmodule

