module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
parameter [31:0] H_ACTIVE=640;
parameter [31:0] H_FRONT=16;
parameter [31:0] H_BACK=96;
parameter [31:0] H_RETRACE=48;
parameter [31:0] V_ACTIVE=480;
parameter [31:0] V_FRONT=10;
parameter [31:0] V_BACK=33;
parameter [31:0] V_RETRACE=2;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      h_count_reg <= {10{1'b0}};
      v_count_reg <= {10{1'b0}};
    end
    else begin
      if((h_count_reg < (H_ACTIVE + H_FRONT + H_BACK + H_RETRACE))) begin
        h_count_reg <= h_count_reg + 1;
      end
      else begin
        h_count_reg <= {10{1'b0}};
        if((v_count_reg < (V_ACTIVE + V_FRONT + V_BACK + V_RETRACE))) begin
          v_count_reg <= v_count_reg + 1;
        end
        else begin
          v_count_reg <= {10{1'b0}};
        end
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      active <= 1'b0;
      hsync <= 1'b0;
      vsync <= 1'b0;
    end
    else begin
      if((h_count_reg < (H_ACTIVE + H_FRONT + H_BACK + H_RETRACE))) begin
        active <= 1'b0;
        hsync <= 1'b0;
        vsync <= 1'b0;
      end
      else begin
        if((h_count_reg < (H_ACTIVE + H_FRONT + H_BACK + H_RETRACE + V_RETRACE))) begin
          active <= 1'b0;
          hsync <= 1'b1;
          vsync <= 1'b0;
        end
        else begin
          if((h_count_reg < (H_ACTIVE + H_FRONT + H_BACK + H_RETRACE + V_RETRACE + V_RETRACE))) begin
            active <= 1'b0;
            hsync <= 1'b0;
            vsync <= 1'b1;
          end
          else begin
            active <= 1'b1;
            hsync <= 1'b0;
            vsync <= 1'b0;
          end
        end
      end
    end
  end
endmodule

