module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );
reg [WIDTH-1:0] state;
wire feedback;
assign feedback = state[TAPS] ^ state[TAPS>>1] ^ state[TAPS>>2] ^ state[TAPS>>3] ^ state[TAPS>>4] ^ state[TAPS>>5] ^ state[TAPS>>6] ^ state[TAPS>>7] ^ state[TAPS>>8] ^ state[TAPS>>9];
always @(posedge clk_i) begin
	if (rst_i) begin
		state <= SEED;
	end else if (next_i) begin
		state <= {state[WIDTH-2:0], feedback};
	end
end
assign output_o = state;
endmodule

