module TopModule(
    input in1,
    input in2,
    input in3,
    output out
    );
xnor x1(out, in1, in2);
xor x2(out, out, in3);
endmodule

module TopModule(
    input clk,
    input d,
    input q
    );
reg q_next;
    always @(posedge clk) begin
        q_next <= d;
    end
    assign q = q_next;
endmodule

