module TopModule(
    input clk,
    input in       [7:0],
    output anyedge [7:0]
    );
wire [7:0] anyedge;
    always @(posedge clk) begin
        anyedge[0] <= in[0] ^ in[1];
        anyedge[1] <= in[1] ^ in[2];
        anyedge[2] <= in[2] ^ in[3];
        anyedge[3] <= in[3] ^ in[4];
        anyedge[4] <= in[4] ^ in[5];
        anyedge[5] <= in[5] ^ in[6];
        anyedge[6] <= in[6] ^ in[7];
        anyedge[7] <= in[7] ^ in[0];
    end
endmodule

