reg [9:0] counter;
always @(posedge clk) begin
    if (load) begin
        counter <= data;
        tc <= 0;
    end
    else begin
        if (counter > 0) begin
            counter <= counter - 1;
            tc <= 0;
        end
        else begin
            counter <= 0;
            tc <= 1;
        end
    end
