    parameter A = 1'b0;
    reg state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= B;
        end else begin
            case (state)
                B: begin
                    if (in == 1'b0) begin
                        state <= A;
                    end
                    else begin
                        state <= B;
                    end
                end
                A: begin
                    if (in == 1'b0) begin
                        state <= B;
                    end
                    else begin
                        state <= A;
                    end
                end
            endcase
        end
    end
    assign out = state;
endmodule

