module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  predict_taken,
    input  train_mispredicted,
    input  train_taken,
    input  [31:0] train_history,
    output [31:0] predict_history
    );
reg [31:0] branch_history;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            branch_history <= 0;
        end else if (predict_valid) begin
            branch_history <= {branch_history[30:0], predict_taken};
        end else if (train_mispredicted) begin
            branch_history <= {train_history, train_taken};
        end
    end
    assign predict_history = branch_history;
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  in,
    output out
    );
parameter [1:0]
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11;

    reg [1:0] state;
    reg out;

    always @(posedge clk or posedge areset)
    begin
        if (areset)
            state <= A;
        else
            case (state)
                A: state <= in ? B : A;
                B: state <= in ? C : B;
                C: state <= in ? A : D;
                D: state <= in ? C : B;
            endcase
    end

    always @(state)
    begin
        case (state)
            A: out <= 1'b0;
            B: out <= 1'b0;
            C: out <= 1'b0;
            D: out <= 1'b1;
        endcase
    end
endmodule

module TopModule(
    input  clk,
    input  reset,
    input  in,
    output out
    );
parameter [1:0]
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11;

    reg [1:0] state;
    reg out;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= A;
            out <= 1'b0;
        end
        else begin
            case (state)
                A: begin
                    if (in) begin
                        state <= B;
                        out <= 1'b0;
                    end
                    else begin
                        state <= A;
                        out <= 1'b0;
                    end
                end
                B: begin
                    if (in) begin
                        state <= C;
                        out <= 1'b0;
                    end
                    else begin
                        state <= B;
                        out <= 1'b0;
                    end
                end
                C: begin
                    if (in) begin
                        state <= A;
                        out <= 1'b0;
                    end
                    else begin
                        state <= D;
                        out <= 1'b0;
                    end
                end
                D: begin
                    if (in) begin
                        state <= C;
                        out <= 1'b0;
                    end
                    else begin
                        state <= B;
                        out <= 1'b1;
                    end
                end
            endcase
        end
    end
endmodule

