        if (load) begin
            q <= data;
        end else begin
            q[0] <= 0;
            q[511] <= 0;
            for (int i = 1; i < 511; i = i + 1) begin
                case ({q[i+1], q[i], q[i-1]})
                    3'b111: q[i] <= 0;
                    3'b110: q[i] <= 1;
                    3'b101: q[i] <= 1;
                    3'b100: q[i] <= 0;
                    3'b011: q[i] <= 1;
                    3'b010: q[i] <= 1;
