module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
    );
reg state;
    reg next_state;
    reg walk_left_reg;
    reg walk_right_reg;
    reg bump_left_reg;
    reg bump_right_reg;
    reg bump_left_next;
    reg bump_right_next;
    reg walk_left_next;
    reg walk_right_next;
    reg state_next;
    assign walk_left = walk_left_reg;
    assign walk_right = walk_right_reg;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 1'b0;
            walk_left_reg <= 1'b0;
            walk_right_reg <= 1'b1;
            bump_left_reg <= 1'b0;
            bump_right_reg <= 1'b0;
        end
        else begin
            state <= state_next;
            walk_left_reg <= walk_left_next;
            walk_right_reg <= walk_right_next;
            bump_left_reg <= bump_left_next;
            bump_right_reg <= bump_right_next;
        end
    end
    always @(state or bump_left or bump_right) begin
        case (state)
            1'b0: begin
                state_next = bump_left ? 1'b1 : 1'b0;
                bump_left_next = 1'b0;
                bump_right_next = 1'b0;
                walk_left_next = 1'b0;
                walk_right_next = 1'b1;
            end
            1'b1: begin
                state_next = bump_right ? 1'b0 : 1'b1;
                bump_left_next = 1'b0;
                bump_right_next = 1'b0;
                walk_left_next = 1'b1;
                walk_right_next = 1'b0;
            end
        endcase
    end
endmodule

