reg z;
reg [1:0] state;
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        z <= 1'b0;
    end
    else begin
        case (state)
            2'b00: begin
                if (s == 1'b0) begin
                    state <= 2'b00;
                end
                else begin
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (w == 1'b1) begin
                    z <= 1'b1;
                end
                else begin
                    z <= 1'b0;
                end
                state <= 2'b10;
            end
            2'b10: begin
                if (w == 1'b1) begin
                    z <= 1'b1;
                end
                else begin
                    z <= 1'b0;
                end
                state <= 2'b11;
            end
            2'b11: begin
                if (w == 1'b1) begin
                    z <= 1'b1;
                end
                else begin
                    z <= 1'b0;
                end
                state <= 2'b00;
            end
        endcase
    end
end
endmodule

