module TopModule(
    input  clk,
    input  resetn,
    input  r (3 bits),
    output g (3 bits)
    );
reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] g;
    reg [2:0] next_g;
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            g <= 3'b000;
        end else begin
            g <= next_g;
        end
    end
    always @(*) begin
        next_state = state;
        next_g = g;
        case (state)
            2'b00: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end else if (r[0] == 1'b1) begin
                    next_state = 2'b01;
                end else if (r[0] == 1'b0 && r[1] == 1'b1) begin
                    next_state = 2'b10;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b11;
                end
            end
            2'b01: begin
                if (r[0] == 1'b1) begin
                    next_state = 2'b01;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end
            end
            2'b10: begin
                if (r[0] == 1'b0 && r[1] == 1'b1) begin
                    next_state = 2'b10;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end
            end
            2'b11: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end
            end
        endcase
        case (state)
            2'b00: begin
                next_g = 3'b000;
            end
            2'b01: begin
                next_g = 3'b001;
            end
            2'b10: begin
                next_g = 3'b010;
            end
            2'b11: begin
                next_g = 3'b100;
            end
        endcase
    end
endmodule

