module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);
parameter [1:0]
    S_IDLE = 2'b00,
    S_WAIT = 2'b01,
    S_COUNT = 2'b10,
    S_DONE = 2'b11;

reg [1:0] state;
reg [1:0] next_state;
reg [1:0] shift_ena_reg;
reg [1:0] shift_ena_next;
reg [1:0] counting_reg;
reg [1:0] counting_next;
reg [1:0] done_reg;
reg [1:0] done_next;

assign shift_ena = shift_ena_reg;
assign counting = counting_reg;
assign done = done_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

always @(state, data) begin
    case (state)
        S_IDLE: begin
            if (data == 4'b1101) begin
                next_state = S_WAIT;
            end else begin
                next_state = S_IDLE;
            end
        end
        S_WAIT: begin
            next_state = S_WAIT;
        end
        S_COUNT: begin
            next_state = S_COUNT;
        end
        S_DONE: begin
            next_state = S_DONE;
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

always @(state, data) begin
    case (state)
        S_IDLE: begin
            shift_ena_next = 2'b00;
            counting_next = 2'b00;
            done_next = 2'b00;
        end
        S_WAIT: begin
            shift_ena_next = 2'b00;
            counting_next = 2'b00;
            done_next = 2'b00;
        end
        S_COUNT: begin
            shift_ena_next = 2'b00;
            counting_next = 2'b00;
            done_next = 2'b00;
        end
        S_DONE: begin
            shift_ena_next = 2'b00;
            counting_next = 2'b00;
            done_next = 2'b00;
        end
        default: begin
            shift_ena_next = 2'b00;
            counting_next = 2'b00;
            done_next = 2'b00;
        end
    endcase
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        shift_ena_reg <= 2'b00;
    end else begin
        shift_ena_reg <= shift_ena_next;
    end
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counting_reg <= 2'b00;
    end else begin
        counting_reg <= counting_next;
    end
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        done_reg <= 2'b00;
    end else begin
        done_reg <= done_next;
    end
end

endmodule

