        next_state = in ? 4'b0000 : 4'b0001;
        out = 0;
      end
      4'b0010: begin
        next_state = in ? 4'b0000 : 4'b0010;
        out = 0;
      end
      4'b0100: begin
        next_state = in ? 4'b0000 : 4'b0100;
        out = 0;
      end
