module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
parameter A = 0;
  parameter B = 1;
  parameter C = 2;
  parameter D = 3;

  reg [1:0] state;
  reg [2:0] g;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= A;
    end else begin
      case (state)
        A: if (!r[0] && !r[1] && !r[2]) begin
            state <= A;
          end else if (r[0]) begin
            state <= B;
          end else if (r[1]) begin
            state <= C;
          end else begin
            state <= D;
          end
        B: if (!r[0] && !r[1] && !r[2]) begin
            state <= A;
          end else if (r[0]) begin
            state <= B;
          end else begin
            state <= A;
          end
        C: if (!r[0] && !r[1] && !r[2]) begin
            state <= A;
          end else if (r[1]) begin
            state <= C;
          end else begin
            state <= A;
          end
        D: if (!r[0] && !r[1] && !r[2]) begin
            state <= A;
          end else if (r[0]) begin
            state <= B;
          end else if (r[1]) begin
            state <= C;
          end else begin
            state <= D;
          end
      endcase
    end
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      g <= 3'b000;
    end else begin
      case (state)
        A: g <= 3'b000;
        B: g <= 3'b001;
        C: g <= 3'b010;
        D: g <= 3'b000;
      endcase
    end
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input [2:0] s,
  output reg fr2,
  output reg fr1,
  output reg fr0,
  output reg dfr
);
always @(posedge clk or posedge reset) begin
    if (reset) begin
      fr2 <= 1'b0;
      fr1 <= 1'b0;
      fr0 <= 1'b0;
      dfr <= 1'b0;
    end else begin
      if (s[2]) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b0;
        dfr <= 1'b0;
      end else if (s[1]) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b1;
        dfr <= 1'b0;
      end else if (s[0]) begin
        fr2 <= 1'b0;
        fr1 <= 1'b1;
        fr0 <= 1'b1;
        dfr <= 1'b0;
      end else begin
        fr2 <= 1'b1;
        fr1 <= 1'b1;
        fr0 <= 1'b1;
        dfr <= 1'b1;
      end
    end
  end
endmodule

