module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);
parameter [1:0]
  S_IDLE = 2'b00,
  S_WAIT_START = 2'b01,
  S_WAIT_COUNT = 2'b10,
  S_WAIT_ACK = 2'b11;

  reg [1:0] state;
  reg [1:0] next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= S_IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(state or data or done_counting or ack) begin
    case (state)
      S_IDLE: begin
        next_state = (data == 1'b1) ? S_WAIT_START : S_IDLE;
      end
      S_WAIT_START: begin
        next_state = (data == 1'b0) ? S_WAIT_START : S_WAIT_COUNT;
      end
      S_WAIT_COUNT: begin
        next_state = (done_counting) ? S_WAIT_ACK : S_WAIT_COUNT;
      end
      S_WAIT_ACK: begin
        next_state = (ack) ? S_IDLE : S_WAIT_ACK;
      end
      default: begin
        next_state = S_IDLE;
      end
    endcase
  end

  always @(state or data) begin
    case (state)
      S_IDLE: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
      S_WAIT_START: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
      S_WAIT_COUNT: begin
        shift_ena = 1'b0;
        counting = 1'b1;
        done = 1'b0;
      end
      S_WAIT_ACK: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b1;
      end
      default: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
    endcase
  end

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      shift_ena <= 1'b0;
    end else begin
      shift_ena <= (state == S_WAIT_START) ? 1'b1 : shift_ena;
    end
  end

endmodule

